// EventSink conformance + method bodies for the Daak TurboModule; the method
// table lives in DaakModule.mm. DaakEngine, EventSink and FfiEvent are all
// GENERATED by uniffi_bindgen 0.28.3 from crates/daak-ffi/src/daak.udl -- note
// the module name is daak_ffiFFI, and the class is DaakEngine (the Rust-side
// FfiEngine alias never reaches codegen).
import Foundation
import daak_ffiFFI

@objc(Daak)
final class Daak: RCTEventEmitter, EventSink {
  // One serial queue owns the engine for the promise-returning methods: start,
  // shutdown and every call site touch it, so the handle is never read or
  // written concurrently.
  private let q = DispatchQueue(label: "dev.darshit.daak.engine")
  private var engine: DaakEngine?

  // onEvent arrives on a Rust thread, not on q. It cannot go through q.sync:
  // the engine calls below block_on, which can deliver an event on the very
  // thread already running q, and that would deadlock. So this reference has
  // its own lock, held only long enough to copy the pointer, never across a
  // call into Rust.
  private let eventLock = NSLock()
  private var eventEngine: DaakEngine?

  override func supportedEvents() -> [String]! { ["DaakEvent"] }

  @objc func start(_ dataDir: String, displayName: String, listenPort: Double,
                   resolve: @escaping RCTPromiseResolveBlock, reject: @escaping RCTPromiseRejectBlock) {
    // start runs on the same serial queue, so the handle is stored before the
    // promise settles and no call can observe a half-started engine.
    q.async {
      do {
        // R43: dataDir is IGNORED, not honoured-when-non-empty.
        // InProcessEngine.start() takes no arguments and hardcodes '', so the
        // "use the incoming dir when it is set" branch would be dead code today
        // and a sandbox escape hatch the day the frozen TS path changes.
        // Resolving it here is the only way the invariant "the engine data dir
        // is inside the app sandbox" holds no matter what a caller sends.
        let fm = FileManager.default
        guard let docs = try? fm.url(for: .documentDirectory, in: .userDomainMask,
                                    appropriateFor: nil, create: true) else {
          reject("E_ENGINE", "no writable Documents directory", nil)
          return
        }
        let dataRoot = docs.appendingPathComponent("daak", isDirectory: true)
        // R40(c): a keychain failure REJECTS this start. There is no fallback
        // to a plaintext file store: one that silently regenerates the Ed25519
        // identity and re-pairs the device as a new one, with no error anywhere
        // the user can see.
        // uniffi 0.28.3 lowers the `[Name=new_with_store]` constructor to a
        // STATIC FACTORY, not an init: `DaakEngine.newWithStore(store:sink:)`.
        // A `DaakEngine(store:sink:)` call here is a compile error.
        let e = DaakEngine.newWithStore(store: KeychainSecureStore(), sink: self)
        try e.start(dataDir: dataRoot.path, displayName: displayName, listenPort: UInt16(listenPort))
        self.engine = e
        self.eventLock.lock()
        self.eventEngine = e
        self.eventLock.unlock()
        // Register the ONE wake slot for the native background triggers. The
        // closure hops onto q, because every engine call is serialised there.
        DaakBridge.backgroundWake = { [weak self] in self?.wakeFromNative() }
        resolve(nil)
      } catch { reject("E_ENGINE", String(describing: error), error) }
    }
  }

  @objc func pairingBundle(_ resolve: @escaping RCTPromiseResolveBlock,
                           reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().pairingBundle() }
  }

  @objc func pairWith(_ addr: String, bundleCbor: [NSNumber],
                      resolve: @escaping RCTPromiseResolveBlock,
                      reject: @escaping RCTPromiseRejectBlock) {
    let bytes = bundleCbor.map { UInt8(truncatingIfNeeded: $0.intValue) }
    run(resolve, reject) { try self.need().pairWith(addr: addr, bundleCbor: bytes) }
  }

  // C2 RE-ARM path: the caller holds the peer's bundle, so this takes the same
  // bytes pairWith takes and arms the accept slot for that peer.
  // The trailing `return nil` is load-bearing, exactly as on cancel/retry/
  // setPresence: the generated method returns Void and run<T> takes a
  // `() throws -> T?`, so a single-expression closure leaves T ambiguous and
  // does not type-check.
  @objc func offerPairing(_ bundleCbor: [NSNumber],
                          resolve: @escaping RCTPromiseResolveBlock,
                          reject: @escaping RCTPromiseRejectBlock) {
    let bytes = bundleCbor.map { UInt8(truncatingIfNeeded: $0.intValue) }
    run(resolve, reject) { try self.need().offerPairing(bundleCbor: bytes); return nil as Void? }
  }

  // C2, second review: the host arm spec 3.3 Mode A actually needs. The QR
  // flow is asymmetric -- only the JOINER scans, so the host never holds the
  // joiner's bundle, and an arm that requires one is unreachable. This takes
  // NO argument: the engine learns the peer's identity in-band and verifies it
  // in the Noise XX handshake, and the user comparing the two SAS values is
  // what binds it to a human. See PendingArm::Open in crates/daak-core.
  //
  // The trailing `return nil` is load-bearing, exactly as on cancel/retry/
  // setPresence: the generated method returns Void and run<T> takes a
  // `() throws -> T?`, so a single-expression closure leaves T ambiguous and
  // does not type-check.
  @objc func armHostPairing(_ resolve: @escaping RCTPromiseResolveBlock,
                            reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().armHostPairing(); return nil as Void? }
  }

  @objc func acceptPairing(_ resolve: @escaping RCTPromiseResolveBlock,
                           reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().acceptPairing() }
  }

  @objc func sendText(_ peerId: String, text: String,
                      resolve: @escaping RCTPromiseResolveBlock,
                      reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().sendText(peerId: peerId, text: text) }
  }

  @objc func sendFiles(_ peerId: String, paths: [String],
                       resolve: @escaping RCTPromiseResolveBlock,
                       reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().sendFiles(peerId: peerId, paths: paths) }
  }

  @objc func listDevices(_ resolve: @escaping RCTPromiseResolveBlock,
                         reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().listDevices() }
  }

  @objc func cancel(_ transferId: String,
                    resolve: @escaping RCTPromiseResolveBlock,
                    reject: @escaping RCTPromiseRejectBlock) {
    // The trailing return nil is load-bearing: the generated method returns
    // Void, and resolve() has nothing to hand JS.
    run(resolve, reject) { try self.need().cancel(transferId: transferId); return nil as Void? }
  }

  @objc func retry(_ transferId: String,
                   resolve: @escaping RCTPromiseResolveBlock,
                   reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().retry(transferId: transferId); return nil as Void? }
  }

  @objc func revokePairing(_ deviceId: String,
                           resolve: @escaping RCTPromiseResolveBlock,
                           reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) {
      try self.need().revokePairing(deviceId: deviceId)
      return nil as Void?
    }
  }

  /// The SAS compare matched: a pending pairing becomes trusted.
  @objc func confirmPairing(_ deviceId: String,
                            resolve: @escaping RCTPromiseResolveBlock,
                            reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) {
      try self.need().confirmPairing(deviceId: deviceId)
      return nil as Void?
    }
  }

  /// Drain the outbox now. The ONE wake primitive; InProcessEngine calls this
  /// as backgroundWake(), and the iOS BGTask handler calls it too.
  @objc func backgroundWake(_ resolve: @escaping RCTPromiseResolveBlock,
                            reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) {
      try self.need().backgroundWake()
      return nil as Void?
    }
  }

  @objc func replaceInboxPaths(_ payloadId: String,
                               paths: [String],
                               resolve: @escaping RCTPromiseResolveBlock,
                               reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) {
      try self.need().replaceInboxPaths(payloadId: payloadId, paths: paths)
      return nil as Void?
    }
  }

  @objc func retryItem(_ transferId: String,
                       itemIndex: Double,
                       resolve: @escaping RCTPromiseResolveBlock,
                       reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) {
      try self.need().retryItem(transferId: transferId, itemIndex: UInt32(itemIndex))
      return nil as Void?
    }
  }

  @objc func quarantineReport(_ transferId: String,
                              itemIndex: Double,
                              resolve: @escaping RCTPromiseResolveBlock,
                              reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) {
      try self.need().quarantineReport(transferId: transferId, itemIndex: UInt32(itemIndex))
    }
  }

  @objc func listQuarantineReports(_ resolve: @escaping RCTPromiseResolveBlock,
                                   reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().listQuarantineReports() }
  }

  @objc func deleteQuarantined(_ transferId: String,
                               itemIndex: Double,
                               resolve: @escaping RCTPromiseResolveBlock,
                               reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) {
      try self.need().deleteQuarantined(transferId: transferId, itemIndex: UInt32(itemIndex))
      return nil as Void?
    }
  }

  @objc func listTransfers(_ filterJson: String,
                           resolve: @escaping RCTPromiseResolveBlock,
                           reject: @escaping RCTPromiseRejectBlock) {
    // The UDL has no map type, so the filter crosses as JSON; "" and "{}"
    // both mean no filter and the Rust parser turns both into None.
    run(resolve, reject) { try self.need().listTransfers(filterJson: filterJson) }
  }
  @objc func listThread(_ peerId: String,
                         limit: Double,
                         before: String,
                         resolve: @escaping RCTPromiseResolveBlock,
                         reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) {
      try self.need().listThread(peerId: peerId, limit: UInt32(min(max(0, limit.isFinite ? limit : 0), 4294967295)), before: before)
    }
  }

  @objc func listInbox(_ resolve: @escaping RCTPromiseResolveBlock,
                      reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().listInbox() }
  }

  @objc func selfProfile(_ resolve: @escaping RCTPromiseResolveBlock,
                         reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().selfProfile() }
  }

  @objc func setDisplayName(_ name: String,
                           resolve: @escaping RCTPromiseResolveBlock,
                           reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().setDisplayName(name: name); return nil as Void? }
  }

  @objc func setPresence(_ state: String,
                        resolve: @escaping RCTPromiseResolveBlock,
                        reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().setPresence(state: state); return nil as Void? }
  }

  @objc func localPort(_ resolve: @escaping RCTPromiseResolveBlock,
                       reject: @escaping RCTPromiseRejectBlock) {
    run(resolve, reject) { try self.need().localPort() }
  }

  @objc func shutdown(_ resolve: @escaping RCTPromiseResolveBlock,
                      reject: @escaping RCTPromiseRejectBlock) {
    q.async {
      do {
        let e = self.engine
        self.engine = nil
        self.eventLock.lock()
        self.eventEngine = nil
        self.eventLock.unlock()
        DaakBridge.backgroundWake = nil
        try e?.shutdown()
        resolve(nil)
      } catch { reject("E_DAAK", String(describing: error), error) }
    }
  }

  /// Called from a native background trigger thread. Hops onto q, because the
  /// engine handle is only ever touched there.
  private func wakeFromNative() {
    // The UDL marks background_wake as throwing, so the call needs `try`. A
    // failure here only means the engine is already gone. A native trigger has
    // no JS promise to reject, so the error is dropped.
    q.async { try? self.engine?.backgroundWake() }
  }

  // The generated EventSink callback, invoked on a Rust thread. The UDL hands
  // us an FfiEvent rather than a string, so the generated ffiEventJson turns it
  // into the DaakEvent JSON that packages/core/src/engine/types.ts defines.
  func onEvent(event: FfiEvent) {
    do {
      eventLock.lock()
      let e = eventEngine
      eventLock.unlock()
      guard let e else { return }
      let json = try e.ffiEventJson(ev: event)
      sendEvent(withName: "DaakEvent", body: ["event": json])
    } catch {
      // A Rust thread cannot reject a JS promise, so the only honest channel
      // for a conversion failure is the log.
      NSLog("Daak: ffiEventJson failed: \(error)")
    }
  }

  // Every engine call blocks on the engine tokio runtime, so none of it runs
  // on the JS or main thread. Engine access is serialised on q; block returns
  // nil for the Void-returning methods.
  private func run<T>(_ resolve: @escaping RCTPromiseResolveBlock,
                      _ reject: @escaping RCTPromiseRejectBlock,
                      _ block: @escaping () throws -> T?) {
    q.async {
      do { resolve(try block()) }
      catch { reject("E_DAAK", String(describing: error), error) }
    }
  }

  // Must be called on q. A nil engine is a caller bug, so it rejects instead of
  // resolving undefined the way a bare self.engine? would.
  private func need() throws -> DaakEngine {
    guard let e = engine else { throw DaakError.notStarted }
    return e
  }
}

private enum DaakError: Error {
  case notStarted
}
